"use client";

import { useState, useEffect, use } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { ArrowLeft, Save, Loader2, AlertCircle, Trash2 } from "lucide-react";

export default function EditPolicyPage(props: { params: Promise<{ id: string }> }) {
    const params = use(props.params);
    const router = useRouter();
    const [loading, setLoading] = useState(false);
    const [fetching, setFetching] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [policy, setPolicy] = useState<any>(null);

    useEffect(() => {
        const fetchPolicy = async () => {
            try {
                const res = await fetch(`/api/admin/policies/${params.id}`);
                if (!res.ok) throw new Error("Failed to fetch policy");
                const data = await res.json();
                setPolicy(data);
            } catch (err: any) {
                setError(err.message);
            } finally {
                setFetching(false);
            }
        };
        fetchPolicy();
    }, [params.id]);

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setLoading(true);
        setError(null);

        const formData = new FormData(e.currentTarget);
        const data = {
            name: formData.get("name"),
            description: formData.get("description"),
            clauseType: formData.get("clauseType"),
            rate: formData.get("rate"),
            minPremium: formData.get("minPremium"),
            currency: formData.get("currency"),
            isActive: formData.get("isActive") === "on",
        };

        try {
            const res = await fetch(`/api/admin/policies/${params.id}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(data),
            });

            if (!res.ok) {
                const errorData = await res.json();
                throw new Error(errorData.error || "Failed to update policy");
            }

            router.push("/admin/policies");
            router.refresh();
        } catch (err: any) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async () => {
        if (!confirm("Are you sure you want to delete this policy? If it has been used, it will be deactivated instead.")) return;

        setLoading(true);
        try {
            const res = await fetch(`/api/admin/policies/${params.id}`, {
                method: "DELETE",
            });

            if (!res.ok) {
                const errorData = await res.json();
                throw new Error(errorData.error || "Failed to delete policy");
            }

            router.push("/admin/policies");
            router.refresh();
        } catch (err: any) {
            setError(err.message);
            setLoading(false);
        }
    };

    if (fetching) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <Loader2 className="w-8 h-8 animate-spin text-brand-green" />
            </div>
        );
    }

    if (!policy) {
        return (
            <div className="p-6 text-center">
                <p className="text-red-500 mb-4">Policy not found</p>
                <Link href="/admin/policies" className="text-brand-green hover:underline">
                    Back to Policies
                </Link>
            </div>
        );
    }

    return (
        <div className="p-6 max-w-4xl mx-auto">
            <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-4">
                    <Link
                        href="/admin/policies"
                        className="p-2 -ml-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition"
                    >
                        <ArrowLeft className="w-5 h-5" />
                    </Link>
                    <div>
                        <h1 className="text-2xl font-bold text-slate-900">Edit Policy</h1>
                        <p className="text-slate-500">Update insurance product details</p>
                    </div>
                </div>
                <button
                    onClick={handleDelete}
                    disabled={loading}
                    className="flex items-center gap-2 text-red-600 hover:bg-red-50 px-4 py-2 rounded-lg transition"
                >
                    <Trash2 className="w-4 h-4" />
                    Delete Policy
                </button>
            </div>

            <form onSubmit={handleSubmit} className="bg-white rounded-xl border border-slate-200 shadow-sm p-6 space-y-8">
                {error && (
                    <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-lg flex items-center gap-2 text-sm">
                        <AlertCircle className="w-4 h-4" />
                        {error}
                    </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">Policy Name <span className="text-red-500">*</span></label>
                        <input
                            name="name"
                            required
                            defaultValue={policy.name}
                            className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:border-brand-green focus:ring-1 focus:ring-brand-green outline-none transition"
                        />
                    </div>

                    <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">Policy Code</label>
                        <input
                            disabled
                            value={policy.code}
                            className="w-full px-4 py-2 rounded-lg border border-slate-200 bg-slate-50 text-slate-500 cursor-not-allowed"
                        />
                        <p className="text-xs text-slate-400">Code cannot be changed once created</p>
                    </div>

                    <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">Clause Type <span className="text-red-500">*</span></label>
                        <select
                            name="clauseType"
                            required
                            defaultValue={policy.clauseType}
                            className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:border-brand-green focus:ring-1 focus:ring-brand-green outline-none transition"
                        >
                            <option value="">Select Clause Type</option>
                            <option value="ICC(A)">Institute Cargo Clauses (A)</option>
                            <option value="ICC(B)">Institute Cargo Clauses (B)</option>
                            <option value="ICC(C)">Institute Cargo Clauses (C)</option>
                            <option value="AIR">Institute Cargo Clauses (Air)</option>
                        </select>
                    </div>

                    <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">Currency</label>
                        <select
                            name="currency"
                            defaultValue={policy.currency}
                            className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:border-brand-green focus:ring-1 focus:ring-brand-green outline-none transition"
                        >
                            <option value="USD">USD - US Dollar</option>
                            <option value="TZS">TZS - Tanzanian Shilling</option>
                            <option value="EUR">EUR - Euro</option>
                        </select>
                    </div>

                    <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">Premium Rate (%) <span className="text-red-500">*</span></label>
                        <input
                            type="number"
                            name="rate"
                            required
                            step="0.01"
                            min="0"
                            defaultValue={policy.rate}
                            className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:border-brand-green focus:ring-1 focus:ring-brand-green outline-none transition"
                        />
                    </div>

                    <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">Minimum Premium</label>
                        <input
                            type="number"
                            name="minPremium"
                            step="0.01"
                            min="0"
                            defaultValue={policy.minPremium}
                            className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:border-brand-green focus:ring-1 focus:ring-brand-green outline-none transition"
                        />
                    </div>
                </div>

                <div className="space-y-2">
                    <label className="text-sm font-medium text-slate-700">Description</label>
                    <textarea
                        name="description"
                        rows={4}
                        defaultValue={policy.description}
                        className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:border-brand-green focus:ring-1 focus:ring-brand-green outline-none transition resize-none"
                    />
                </div>

                <div className="flex items-center gap-2">
                    <input
                        type="checkbox"
                        name="isActive"
                        id="isActive"
                        defaultChecked={policy.isActive}
                        className="w-4 h-4 rounded border-slate-300 text-brand-green focus:ring-brand-green"
                    />
                    <label htmlFor="isActive" className="text-sm font-medium text-slate-700 select-none cursor-pointer">
                        Active Policy (Visible to users)
                    </label>
                </div>

                <div className="flex justify-end pt-4 border-t border-slate-100">
                    <button
                        type="submit"
                        disabled={loading}
                        className="flex items-center gap-2 bg-brand-green text-white px-6 py-2.5 rounded-lg hover:bg-green-700 transition disabled:opacity-50 disabled:cursor-not-allowed font-medium shadow-sm shadow-green-200"
                    >
                        {loading ? (
                            <>
                                <Loader2 className="w-4 h-4 animate-spin" />
                                Saving...
                            </>
                        ) : (
                            <>
                                <Save className="w-4 h-4" />
                                Save Changes
                            </>
                        )}
                    </button>
                </div>
            </form>
        </div>
    );
}
